using System.Collections.Frozen;
using System.Text;

namespace MySync.Domain.Paths.Normalization;

/// <summary>
/// Unicode Normalization Form C (UAX #15) without ICU. Release builds run with
/// <c>InvariantGlobalization=true</c>, where <see cref="string.Normalize()"/> silently returns its
/// input unchanged (CLAUDE.md §8), so mysync carries its own implementation and its own tables
/// (<see cref="UnicodeNormalizationData"/>, generated by <c>tools/unicode/GenerateNfcData.cs</c>).
/// The result is the same on every OS and every runtime configuration.
/// </summary>
internal static class NfcNormalizer
{
    // Below U+0300 no character changes under NFC and none composes with a preceding one (the
    // first NFC_Quick_Check=No/Maybe code point is U+0300). Pinned by a unit test.
    internal const char FirstNonTrivialCharacter = '̀';

    // Hangul syllables (Unicode §3.12) are composed and decomposed arithmetically.
    private const int SBase = 0xAC00;
    private const int LBase = 0x1100;
    private const int VBase = 0x1161;
    private const int TBase = 0x11A7;
    private const int LCount = 19;
    private const int VCount = 21;
    private const int TCount = 28;
    private const int NCount = VCount * TCount;
    private const int SCount = LCount * NCount;

    private static readonly FrozenDictionary<int, (int Start, int Length)> DecompositionIndex = BuildDecompositionIndex();
    private static readonly FrozenDictionary<long, int> CompositionIndex = BuildCompositionIndex();

    internal static string UnicodeVersion => UnicodeNormalizationData.UnicodeVersion;

    /// <summary>
    /// Returns <paramref name="value"/> in NFC. Returns the same instance when it already is.
    /// Unpaired surrogates are passed through unchanged (they have no decomposition and class 0).
    /// </summary>
    public static string Normalize(string value)
    {
        ArgumentNullException.ThrowIfNull(value);

        foreach (char c in value)
        {
            if (c >= FirstNonTrivialCharacter)
            {
                return NormalizeCore(value);
            }
        }

        return value;
    }

    /// <summary>The full algorithm with no fast path. Internal for tests.</summary>
    internal static string NormalizeCore(string value)
    {
        List<int> codePoints = new(value.Length + 8);

        int i = 0;

        while (i < value.Length)
        {
            int codePoint = value[i];
            int width = 1;

            if (char.IsHighSurrogate(value[i]) && i + 1 < value.Length && char.IsLowSurrogate(value[i + 1]))
            {
                codePoint = char.ConvertToUtf32(value[i], value[i + 1]);
                width = 2;
            }

            AppendDecomposition(codePoint, codePoints);
            i += width;
        }

        ApplyCanonicalOrdering(codePoints);
        Compose(codePoints);

        string result = ToString(codePoints, value.Length);

        return string.Equals(result, value, StringComparison.Ordinal) ? value : result;
    }

    /// <summary>
    /// Canonical decomposition (NFD: decompose, then canonical ordering), from the same generated
    /// data. Used to strip accents for share-name suggestions (<c>ShareName.SuggestFrom</c>).
    /// </summary>
    internal static string Decompose(string value)
    {
        ArgumentNullException.ThrowIfNull(value);
        List<int> codePoints = new(value.Length + 8);

        int i = 0;
        while (i < value.Length)
        {
            int codePoint = value[i];
            int width = 1;

            if (char.IsHighSurrogate(value[i]) && i + 1 < value.Length && char.IsLowSurrogate(value[i + 1]))
            {
                codePoint = char.ConvertToUtf32(value[i], value[i + 1]);
                width = 2;
            }

            AppendDecomposition(codePoint, codePoints);
            i += width;
        }

        ApplyCanonicalOrdering(codePoints);
        return ToString(codePoints, value.Length);
    }

    internal static int GetCombiningClass(int codePoint)
    {
        ReadOnlySpan<int> ranges = UnicodeNormalizationData.CombiningClassRanges;
        int low = 0;
        int high = ranges.Length / 3 - 1;

        while (low <= high)
        {
            int middle = low + (high - low) / 2;
            int start = ranges[middle * 3];
            int end = ranges[middle * 3 + 1];

            if (codePoint < start)
            {
                high = middle - 1;
            }
            else if (codePoint > end)
            {
                low = middle + 1;
            }
            else
            {
                return ranges[middle * 3 + 2];
            }
        }

        return 0;
    }

    private static void AppendDecomposition(int codePoint, List<int> target)
    {
        int syllableIndex = codePoint - SBase;

        if (syllableIndex is >= 0 and < SCount)
        {
            target.Add(LBase + syllableIndex / NCount);
            target.Add(VBase + syllableIndex % NCount / TCount);

            int trailing = syllableIndex % TCount;
            if (trailing != 0)
            {
                target.Add(TBase + trailing);
            }

            return;
        }

        if (DecompositionIndex.TryGetValue(codePoint, out (int Start, int Length) entry))
        {
            ReadOnlySpan<int> mapping = UnicodeNormalizationData.Decompositions.Slice(entry.Start, entry.Length);

            foreach (int part in mapping)
            {
                target.Add(part);
            }

            return;
        }

        target.Add(codePoint);
    }

    // Stable sort of every run of non-starters by combining class (Unicode §3.11, D109).
    private static void ApplyCanonicalOrdering(List<int> codePoints)
    {
        for (int i = 1; i < codePoints.Count; i++)
        {
            int current = codePoints[i];
            int currentClass = GetCombiningClass(current);

            if (currentClass == 0)
            {
                continue;
            }

            int j = i - 1;

            while (j >= 0)
            {
                int previousClass = GetCombiningClass(codePoints[j]);

                if (previousClass <= currentClass)
                {
                    break;
                }

                codePoints[j + 1] = codePoints[j];
                j--;
            }

            codePoints[j + 1] = current;
        }
    }

    // Canonical composition algorithm (Unicode §3.11, D117), in place.
    private static void Compose(List<int> codePoints)
    {
        int starterIndex = -1;
        int lastClass = -1; // class of the last character kept since the starter; -1 = none yet
        int write = 0;

        for (int read = 0; read < codePoints.Count; read++)
        {
            int codePoint = codePoints[read];
            int combiningClass = GetCombiningClass(codePoint);

            // A character is blocked from the starter if something kept in between is a starter
            // or has a class >= its own. The sequence is canonically ordered, so the last kept
            // character carries the highest class of everything in between.
            bool blocked = lastClass != -1 && (lastClass == 0 || lastClass >= combiningClass);

            if (starterIndex >= 0 && !blocked && TryCompose(codePoints[starterIndex], codePoint, out int composite))
            {
                codePoints[starterIndex] = composite;
                continue;
            }

            if (combiningClass == 0)
            {
                starterIndex = write;
                lastClass = -1;
            }
            else
            {
                lastClass = combiningClass;
            }

            codePoints[write++] = codePoint;
        }

        codePoints.RemoveRange(write, codePoints.Count - write);
    }

    private static bool TryCompose(int first, int second, out int composite)
    {
        int leadingIndex = first - LBase;
        int vowelIndex = second - VBase;

        if (leadingIndex is >= 0 and < LCount && vowelIndex is >= 0 and < VCount)
        {
            composite = SBase + (leadingIndex * VCount + vowelIndex) * TCount;
            return true;
        }

        int syllableIndex = first - SBase;
        int trailingIndex = second - TBase;

        if (syllableIndex is >= 0 and < SCount && syllableIndex % TCount == 0 && trailingIndex is > 0 and < TCount)
        {
            composite = first + trailingIndex;
            return true;
        }

        return CompositionIndex.TryGetValue(PairKey(first, second), out composite);
    }

    private static long PairKey(int first, int second) => ((long)first << 21) | (uint)second;

    private static string ToString(List<int> codePoints, int capacity)
    {
        StringBuilder builder = new(capacity);

        foreach (int codePoint in codePoints)
        {
            if (codePoint > char.MaxValue)
            {
                builder.Append(char.ConvertFromUtf32(codePoint));
            }
            else
            {
                // Also covers unpaired surrogates, which ConvertFromUtf32 would reject.
                builder.Append((char)codePoint);
            }
        }

        return builder.ToString();
    }

    private static FrozenDictionary<int, (int Start, int Length)> BuildDecompositionIndex()
    {
        ReadOnlySpan<int> data = UnicodeNormalizationData.Decompositions;
        Dictionary<int, (int Start, int Length)> index = [];

        for (int i = 0; i < data.Length;)
        {
            int length = data[i + 1];
            index[data[i]] = (i + 2, length);
            i += 2 + length;
        }

        return index.ToFrozenDictionary();
    }

    private static FrozenDictionary<long, int> BuildCompositionIndex()
    {
        ReadOnlySpan<int> data = UnicodeNormalizationData.Compositions;
        Dictionary<long, int> index = [];

        for (int i = 0; i < data.Length; i += 3)
        {
            index[PairKey(data[i], data[i + 1])] = data[i + 2];
        }

        return index.ToFrozenDictionary();
    }
}
